// Stack and Queue Implementation in Java

public class StackAndQueue {

    // Node class for the stack and queue
    private static class Node {
        int data;
        Node next;

        Node(int data) {
            this.data = data;
            this.next = null;
        }
    }

    // Stack class
    private static class Stack {
        Node top;

        public void push(int data) {
            Node newNode = new Node(data);
            if (top == null) {
                top = newNode;
            } else {
                newNode.next = top;
                top = newNode;
            }
        }

        public int pop() {
            if (top == null) {
                throw new RuntimeException("Stack is empty");
            }
            int data = top.data;
            top = top.next;
            return data;
        }

        public boolean isEmpty() {
            return top == null;
        }
    }

    // Queue class
    private static class Queue {
        Node front;
        Node rear;

        public void enqueue(int data) {
            Node newNode = new Node(data);
            if (front == null) {
                front = newNode;
                rear = newNode;
            } else {
                rear.next = newNode;
                rear = newNode;
            }
        }

        public int dequeue() {
            if (front == null) {
                throw new RuntimeException("Queue is empty");
            }
            int data = front.data;
            front = front.next;
            if (front == null) {
                rear = null;
            }
            return data;
        }

        public boolean isEmpty() {
            return front == null;
        }
    }

    public static void main(String[] args) {
        // Test the stack
        Stack stack = new Stack();
        stack.push(1);
        stack.push(2);
        stack.push(3);
        System.out.println("Popped element: " + stack.pop()); // prints 3
        System.out.println("Popped element: " + stack.pop()); // prints 2
        System.out.println("Popped element: " + stack.pop()); // prints 1
        System.out.println("Is stack empty: " + stack.isEmpty()); // prints true

        // Test the queue
        Queue queue = new Queue();
        queue.enqueue(1);
        queue.enqueue(2);
        queue.enqueue(3);
        System.out.println("Dequeued element: " + queue.dequeue()); // prints 1
        System.out.println("Dequeued element: " + queue.dequeue()); // prints 2
        System.out.println("Dequeued element: " + queue.dequeue()); // prints 3
        System.out.println("Is queue empty: " + queue.isEmpty()); // prints true
    }
}
